describe("WeightBasedShippingCalculator", () => {
  it("rejects empty brackets", () => {
    expect(() => new WeightBasedShippingCalculator([])).toThrow();
  });

  it("rejects bracket with non-positive upToGrams", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
    ).toThrow(RangeError);
  });

  it("rejects bracket with negative costCents", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: -1 }]),
    ).toThrow(RangeError);
  });

  it("rejects non-integer overflowCostCents", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: 100 }], 5.5),
    ).toThrow(RangeError);
  });

  it("rejects negative overflowCostCents", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: 100 }], -1),
    ).toThrow(RangeError);
  });

  it("returns 0 for empty cart", () => {
    const calc = new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: 500 }]);
    expect(calc.computeShippingCents([], 5000)).toBe(0);
  });

  it("returns 0 for zero-weight items", () => {
    const calc = new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: 500 }]);
    expect(calc.computeShippingCents([makeLine("a", undefined, 2)], 5000)).toBe(0);
  });

  it("selects correct bracket", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
      { upToGrams: 2000, costCents: 900 },
    ]);
    // 400g → first bracket
    expect(calc.computeShippingCents([makeLine("a", 400)], 5000)).toBe(300);
    // 500g → first bracket (boundary, inclusive)
    expect(calc.computeShippingCents([makeLine("a", 500)], 5000)).toBe(300);
    // 501g → second bracket
    expect(calc.computeShippingCents([makeLine("a", 501)], 5000)).toBe(600);
    // 1000g → second bracket (boundary)
    expect(calc.computeShippingCents([makeLine("a", 1000)], 5000)).toBe(600);
    // 1001g → third bracket
    expect(calc.computeShippingCents([makeLine("a", 1001)], 5000)).toBe(900);
  });

  it("uses overflow cost when weight exceeds all brackets", () => {
    const calc = new WeightBasedShippingCalculator(
      [{ upToGrams: 500, costCents: 300 }, { upToGrams: 1000, costCents: 600 }],
      1200,
    );
    expect(calc.computeShippingCents([makeLine("a", 1500)], 5000)).toBe(1200);
  });

  it("falls back to heaviest bracket cost when no overflow specified", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    expect(calc.computeShippingCents([makeLine("a", 5000)], 5000)).toBe(600);
  });

  it("sorts brackets regardless of input order", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 2000, costCents: 900 },
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    expect(calc.computeShippingCents([makeLine("a", 400)], 5000)).toBe(300);
  });

  it("sums weight across lines", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    // 200g * 3 = 600g → second bracket
    expect(calc.computeShippingCents([makeLine("a", 200, 3)], 5000)).toBe(600);
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";

const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Gadget", unitPriceCents: 2500, weightGrams: 300 };

describe("Cart - line management", () => {
  it("add() increases item count", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    expect(cart.itemCount).toBe(2);
  });

  it("add() merges quantity for same product", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    cart.add(productA, 3);
    expect(cart.itemCount).toBe(5);
  });

  it("add() rejects non-positive quantity", () => {
    const cart = new Cart();
    expect(() => cart.add(productA, 0)).toThrow(RangeError);
    expect(() => cart.add(productA, -1)).toThrow(RangeError);
  });

  it("add() rejects non-integer quantity", () => {
    const cart = new Cart();
    expect(() => cart.add(productA, 1.5)).toThrow(RangeError);
  });

  it("add() rejects negative unit price", () => {
    const cart = new Cart();
    const bad: Product = { id: "x", name: "Bad", unitPriceCents: -1 };
    expect(() => cart.add(bad, 1)).toThrow(RangeError);
  });

  it("remove() returns true and removes existing product", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("remove() returns false for unknown id", () => {
    const cart = new Cart();
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updateQuantity() changes quantity", () => {
    const cart = new Cart();
    cart.add(productA, 5);
    cart.updateQuantity("a", 2);
    expect(cart.itemCount).toBe(2);
  });

  it("updateQuantity(0) removes the product", () => {
    const cart = new Cart();
    cart.add(productA, 3);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
  });

  it("updateQuantity() throws for unknown product", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("unknown", 5)).toThrow();
  });

  it("updateQuantity() rejects negative", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("clear() empties the cart", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    cart.add(productB, 1);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot() returns deep copy", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const snap = cart.snapshot();
    snap[0]!.quantity = 99;
    expect(cart.itemCount).toBe(2);
  });
});

describe("Cart - pricing pipeline", () => {
  it("empty cart has all-zero totals", () => {
    const cart = new Cart();
    const t = cart.totals();
    expect(t.subtotalCents).toBe(0);
    expect(t.discountCents).toBe(0);
    expect(t.taxCents).toBe(0);
    expect(t.shippingCents).toBe(0);
    expect(t.totalCents).toBe(0);
  });

  it("subtotal = sum of unitPrice * quantity", () => {
    const cart = new Cart();
    cart.add(productA, 3); // 3000
    cart.add(productB, 2); // 5000
    expect(cart.totals().subtotalCents).toBe(8000);
  });

  it("applies discount policy and clamps to [0, subtotal]", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({ discountPolicy: mockDiscount });
    cart.add(productA, 2); // subtotal 2000
    const t = cart.totals();
    expect(t.discountCents).toBe(500);
    expect(mockDiscount.computeDiscountCents).toHaveBeenCalledWith(2000);
  });

  it("clamps discount that exceeds subtotal", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(99999),
    };
    const cart = new Cart({ discountPolicy: mockDiscount });
    cart.add(productA, 1); // subtotal 1000
    expect(cart.totals().discountCents).toBe(1000);
  });

  it("clamps negative discount to 0", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ discountPolicy: mockDiscount });
    cart.add(productA, 1);
    expect(cart.totals().discountCents).toBe(0);
  });

  it("tax is computed on discounted subtotal", () => {
    const mockTax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(80),
    };
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const cart = new Cart({ discountPolicy: mockDiscount, taxCalculator: mockTax, region: "US-CA" });
    cart.add(productA, 1); // subtotal 1000, discount 200, discountedSubtotal 800
    cart.totals();
    expect(mockTax.computeTaxCents).toHaveBeenCalledWith(800, "US-CA");
  });

  it("shipping receives lines and discounted subtotal", () => {
    const mockShipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(599),
    };
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(300),
    };
    const cart = new Cart({ discountPolicy: mockDiscount, shippingCalculator: mockShipping });
    cart.add(productA, 2); // subtotal 2000, discount 300, discounted 1700
    cart.totals();
    expect(mockShipping.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      1700,
    );
  });

  it("totalCents = discountedSubtotal + tax + shipping", () => {
    const mockDiscount: DiscountPolicy = { computeDiscountCents: () => 500 };
    const mockTax: TaxCalculator = { computeTaxCents: () => 120 };
    const mockShipping: ShippingCalculator = { computeShippingCents: () => 400 };
    const cart = new Cart({
      discountPolicy: mockDiscount,
      taxCalculator: mockTax,
      shippingCalculator: mockShipping,
    });
    cart.add(productA, 3); // subtotal 3000, discount 500, discounted 2500
    const t = cart.totals();
    expect(t.subtotalCents).toBe(3000);
    expect(t.discountCents).toBe(500);
    expect(t.taxCents).toBe(120);
    expect(t.shippingCents).toBe(400);
    expect(t.totalCents).toBe(2500 + 120 + 400);
  });

  it("defaults region to US", () => {
    const mockTax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: mockTax });
    cart.add(productA, 1);
    cart.totals();
    expect(mockTax.computeTaxCents).toHaveBeenCalledWith(expect.any(Number), "US");
  });
});

