  });

  it("rejects bracket with non-positive upToGrams", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
    ).toThrow(RangeError);
  });

  it("rejects bracket with negative costCents", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: -1 }]),
    ).toThrow(RangeError);
  });

  it("rejects non-integer overflowCostCents", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: 100 }], 5.5),
    ).toThrow(RangeError);
  });

  it("rejects negative overflowCostCents", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: 100 }], -1),
    ).toThrow(RangeError);
  });

  it("returns 0 for empty cart", () => {
    const calc = new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: 500 }]);
    expect(calc.computeShippingCents([], 5000)).toBe(0);
  });

  it("returns 0 for zero-weight items", () => {
    const calc = new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: 500 }]);
    expect(calc.computeShippingCents([makeLine("a", undefined, 2)], 5000)).toBe(0);
  });

  it("selects correct bracket", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
      { upToGrams: 2000, costCents: 900 },
    ]);
    // 400g → first bracket
    expect(calc.computeShippingCents([makeLine("a", 400)], 5000)).toBe(300);
    // 500g → first bracket (boundary, inclusive)
    expect(calc.computeShippingCents([makeLine("a", 500)], 5000)).toBe(300);
    // 501g → second bracket
    expect(calc.computeShippingCents([makeLine("a", 501)], 5000)).toBe(600);
    // 1000g → second bracket (boundary)
    expect(calc.computeShippingCents([makeLine("a", 1000)], 5000)).toBe(600);
    // 1001g → third bracket
    expect(calc.computeShippingCents([makeLine("a", 1001)], 5000)).toBe(900);
  });

  it("uses overflow cost when weight exceeds all brackets", () => {
    const calc = new WeightBasedShippingCalculator(
      [{ upToGrams: 500, costCents: 300 }, { upToGrams: 1000, costCents: 600 }],
      1200,
    );
    expect(calc.computeShippingCents([makeLine("a", 1500)], 5000)).toBe(1200);
  });

  it("falls back to heaviest bracket cost when no overflow specified", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    expect(calc.computeShippingCents([makeLine("a", 5000)], 5000)).toBe(600);
  });

  it("sorts brackets regardless of input order", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 2000, costCents: 900 },
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    expect(calc.computeShippingCents([makeLine("a", 400)], 5000)).toBe(300);
  });

  it("sums weight across lines", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    // 200g * 3 = 600g → second bracket
    expect(calc.computeShippingCents([makeLine("a", 200, 3)], 5000)).toBe(600);
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
