import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it("returns 0 for positive subtotal", () => {
    expect(policy.computeDiscountCents(10000)).toBe(0);
  });

  it("returns 0 for zero subtotal", () => {
    expect(policy.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    expect(policy.computeDiscountCents(-500)).toBe(0);
  });
});

describe("PercentageDiscountPolicy", () => {
  it("rejects negative percent", () => {
    expect(() => new PercentageDiscountPolicy(-1)).toThrow(RangeError);
  });

  it("rejects percent > 100", () => {
    expect(() => new PercentageDiscountPolicy(101)).toThrow(RangeError);
  });

  it("rejects NaN", () => {
    expect(() => new PercentageDiscountPolicy(NaN)).toThrow(RangeError);
  });

  it("rejects Infinity", () => {
    expect(() => new PercentageDiscountPolicy(Infinity)).toThrow(RangeError);
  });

  it("allows 0%", () => {
    const p = new PercentageDiscountPolicy(0);
    expect(p.computeDiscountCents(10000)).toBe(0);
  });

  it("allows 100%", () => {
    const p = new PercentageDiscountPolicy(100);
    expect(p.computeDiscountCents(10000)).toBe(10000);
  });

  it("computes 10% of 10000 cents", () => {
    const p = new PercentageDiscountPolicy(10);
    expect(p.computeDiscountCents(10000)).toBe(1000);
  });

  it("rounds down to nearest cent", () => {
    const p = new PercentageDiscountPolicy(33);
    // 33% of 100 = 33.0 → 33
    expect(p.computeDiscountCents(100)).toBe(33);
    // 33% of 101 = 33.33 → 33
    expect(p.computeDiscountCents(101)).toBe(33);
  });

  it("returns 0 for zero subtotal", () => {
    const p = new PercentageDiscountPolicy(50);
    expect(p.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    const p = new PercentageDiscountPolicy(50);
    expect(p.computeDiscountCents(-100)).toBe(0);
  });

  it("handles very large subtotal", () => {
    const p = new PercentageDiscountPolicy(15);
    expect(p.computeDiscountCents(99999999)).toBe(Math.floor(99999999 * 15 / 100));
  });
});

describe("FixedAmountDiscountPolicy", () => {
  it("rejects negative amount", () => {
    expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
  });

  it("rejects non-integer amount", () => {
    expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
  });

  it("allows zero amount", () => {
    const p = new FixedAmountDiscountPolicy(0);
    expect(p.computeDiscountCents(5000)).toBe(0);
  });

  it("returns the fixed amount when subtotal exceeds it", () => {
    const p = new FixedAmountDiscountPolicy(500);
    expect(p.computeDiscountCents(10000)).toBe(500);
  });

  it("caps at subtotal when amount exceeds subtotal", () => {
    const p = new FixedAmountDiscountPolicy(2000);
    expect(p.computeDiscountCents(1000)).toBe(1000);
  });

  it("returns 0 for zero subtotal", () => {
    const p = new FixedAmountDiscountPolicy(500);
    expect(p.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    const p = new FixedAmountDiscountPolicy(500);
    expect(p.computeDiscountCents(-100)).toBe(0);
  });
});

describe("CompositeDiscountPolicy", () => {
  it("rejects empty policy list", () => {
    expect(() => new CompositeDiscountPolicy([])).toThrow();
  });

  describe("sum mode", () => {
    it("sums individual discounts against original subtotal", () => {
      const p = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // 10% of 5000 = 500, plus fixed 200 = 700
      expect(p.computeDiscountCents(5000)).toBe(700);
    });

    it("can exceed subtotal (clamped by Cart, not policy)", () => {
      const p = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(80), new FixedAmountDiscountPolicy(5000)],
        "sum",
      );
      // 80% of 5000 = 4000, fixed min(5000,5000) = 5000, sum = 9000 > 5000
      expect(p.computeDiscountCents(5000)).toBe(9000);
    });

    it("returns 0 for zero subtotal", () => {
      const p = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      expect(p.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const p = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(p.computeDiscountCents(-500)).toBe(0);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const p = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // First: 10% of 1000 = 100, remaining = 900
      // Second: 10% of 900 = 90, remaining = 810
      // Total discount = 190
      expect(p.computeDiscountCents(1000)).toBe(190);
    });

    it("ordering matters in chain mode", () => {
      const big = new FixedAmountDiscountPolicy(800);
      const small = new PercentageDiscountPolicy(50);

      const bigFirst = new CompositeDiscountPolicy([big, small], "chain");
      const smallFirst = new CompositeDiscountPolicy([small, big], "chain");

      // bigFirst: 800 off 1000 → remaining 200, then 50% of 200 = 100, total = 900
      expect(bigFirst.computeDiscountCents(1000)).toBe(900);
      // smallFirst: 50% of 1000 = 500 → remaining 500, then min(800,500) = 500, total = 1000
      expect(smallFirst.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const p = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(p.computeDiscountCents(0)).toBe(0);
    });

    it("caps each step at remaining", () => {
      const p = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(600), new FixedAmountDiscountPolicy(600)],
        "chain",
      );
      // First: min(600, 1000) = 600, remaining = 400
      // Second: min(600, 400) = 400, remaining = 0
      // Total = 1000
      expect(p.computeDiscountCents(1000)).toBe(1000);
    });
  });

  it("defaults to sum mode", () => {
    const p = new CompositeDiscountPolicy([
      new FixedAmountDiscountPolicy(100),
      new FixedAmountDiscountPolicy(200),
    ]);
    expect(p.computeDiscountCents(5000)).toBe(300);
  });
});

